      {M | ∃ a b : ℝ, M = ![![a, -b], ![b, a]]}
    let G' : Set (Matrix (Fin 2) (Fin 2) ℝ) :=
      G \ ({0} : Set (Matrix (Fin 2) (Fin 2) ℝ))
    ∀ {A B : Matrix (Fin 2) (Fin 2) ℝ},
      A ∈ G' → B ∈ G' → A * B ∈ G' := by
