theorem SO_matrix_group (n : ℕ) :
    let S : Set (Matrix (Fin n) (Fin n) ℝ) :=
      {A | A ∈ Matrix.orthogonalGroup (Fin n) ℝ ∧ A.det = 1}
    (1 ∈ S) ∧ (∀ A ∈ S, ∀ B ∈ S, A * B ∈ S) ∧
      (∀ A ∈ S, IsUnit A ∧ A⁻¹ ∈ S) ∧ IsClosed S := by sorry

