/-- Paths are continuous maps `[0,1] → X`. The concatenation `a * b` is defined
exactly when `a 1 = b 0`, and is given by `a (2t)` on `[0,1/2]` and `b (2t-1)` on `[1/2,1]`.
`(x*y)*z` is defined iff `x*y` is defined and `(x*y)(1) = z(0)`;
`x*(y*z)` is defined iff `y*z` is defined and `x(1) = (y*z)(0)`. -/
theorem path_concat_assoc_defined_iff (X : Type*) [TopologicalSpace X]
    (x y z : C(unitInterval, X)) :
    let concat : (unitInterval → X) → (unitInterval → X) → unitInterval → X :=
      fun a b t =>
        if (t : ℝ) ≤ 1 / 2 then a (Set.projIcc 0 1 zero_le_one (2 * (t : ℝ)))
        else b (Set.projIcc 0 1 zero_le_one (2 * (t : ℝ) - 1))
    (x 1 = y 0 ∧ concat x y 1 = z 0) ↔ (y 1 = z 0 ∧ x 1 = concat y z 0) := by sorry
